begin;
do $test$
declare ua uuid:=gen_random_uuid();ub uuid:=gen_random_uuid();uc uuid:=gen_random_uuid();ha uuid;hb uuid;hc uuid;a uuid;b uuid;placeholder uuid;private_id uuid;personal_id uuid;task uuid;actor uuid;code_a uuid;code_b uuid;doc jsonb;listed jsonb;d date:=(now()at time zone 'America/Sao_Paulo')::date;
begin
 insert into auth.users(id,email)values(ua,'home-a-'||ua||'@example.invalid'),(ub,'home-b-'||ub||'@example.invalid'),(uc,'home-c-'||uc||'@example.invalid');
 perform set_config('request.jwt.claim.sub',ua::text,true);doc:=public.casa_create_household('Casa do casal','A');ha:=(doc->'household'->>'id')::uuid;code_a:=(doc->'household'->>'invite_code')::uuid;
 select id into a from public.casa_members where user_id=ua and household_id=ha;perform public.casa_add_member('B');select id into placeholder from public.casa_members where household_id=ha and name='B';
 private_id:=(public.casa_pair_create('Privado do casal',placeholder)->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',ub::text,true);doc:=public.casa_create_household('Casa criada por engano','B');hb:=(doc->'household'->>'id')::uuid;code_b:=(doc->'household'->>'invite_code')::uuid;
 if public.casa_my_household()<>hb then raise exception 'FAIL: created house not selected';end if;
 perform public.casa_join_household(code_a,'B',placeholder);
 if public.casa_my_household()<>ha then raise exception 'FAIL: existing account could not join invited house';end if;
 select id into b from public.casa_members where user_id=ub and household_id=ha;if b<>placeholder then raise exception 'FAIL: invite did not retain claimed profile';end if;
 if jsonb_array_length(public.casa_household_list())<>2 then raise exception 'FAIL: both memberships not listed';end if;
 if not public.casa_pair_can_access(private_id)then raise exception 'FAIL: private control lost after claiming profile';end if;
 perform public.casa_household_set_default(ha);perform public.casa_household_switch(hb);
 if public.casa_pair_list()<>'[]'::jsonb then raise exception 'FAIL: other house private control mixed in current house';end if;
 perform public.casa_open_default_household();if public.casa_my_household()<>ha then raise exception 'FAIL: default house not restored';end if;
 begin perform public.casa_household_delete(ha,'Casa do casal');raise exception 'FAIL: nonowner deleted shared home';exception when raise_exception then if sqlerrm like 'FAIL:%'then raise;end if;end;
 begin perform public.casa_household_rename(ha,'Wrong');raise exception 'FAIL: nonowner renamed shared home';exception when raise_exception then if sqlerrm like 'FAIL:%'then raise;end if;end;
 begin perform public.casa_household_delete(hb,'wrong name');raise exception 'FAIL: deletion ignored confirmation';exception when raise_exception then if sqlerrm like 'FAIL:%'then raise;end if;end;
 perform public.casa_household_rename(hb,'Casa de teste');perform public.casa_household_delete(hb,'Casa de teste');
 if exists(select 1 from public.casa_households where id=hb)or exists(select 1 from public.casa_tasks where household_id=hb)then raise exception 'FAIL: house deletion incomplete';end if;
 if public.casa_my_household()<>ha or not exists(select 1 from public.casa_households where id=ha)then raise exception 'FAIL: deleting unused house affected shared home';end if;
 -- Two memberships for A also exercise all formerly scalar member lookups.
 perform set_config('request.jwt.claim.sub',ua::text,true);doc:=public.casa_create_household('Outra casa de A','A');hc:=(doc->'household'->>'id')::uuid;
 perform public.casa_household_switch(ha);perform public.casa_pair_save_task(private_id,jsonb_build_object('title','Private','emoji','🌿','assignee_id',a,'starts_on',d,'due_time','18:00','recurrence','daily','interval_days',1,'duration_minutes',10));
 personal_id:=(public.casa_pair_create('Pessoal com várias casas',null)->>'id')::uuid;
 if (select member_a from public.casa_pair_controls where id=personal_id)<>a then raise exception 'FAIL: private creator resolved to a member from another house';end if;
 select id into task from public.casa_pair_tasks where control_id=private_id;
 select effective_member_id into actor from casa_private.pair_assignments(private_id,d)where task_id=task;
 perform public.casa_pair_complete_task(private_id,task,d,actor);
 perform public.casa_pair_undo_completion(private_id,(select id from public.casa_pair_completions where task_id=task));
 select task_id,effective_member_id into task,actor from casa_private.assignments(ha,d)limit 1;
 perform public.casa_complete_task(task,d,actor);
 perform public.casa_undo_completion((select id from public.casa_completions where task_id=task));
 perform public.casa_subscribe_push(jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/test-household-rollback','keys',jsonb_build_object('p256dh',repeat('a',87),'auth',repeat('b',22))));
 perform public.casa_household_switch(hc);
 perform public.casa_subscribe_push(jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/test-household-rollback','keys',jsonb_build_object('p256dh',repeat('a',87),'auth',repeat('b',22))));
 if not exists(select 1 from public.casa_push_subscriptions s join public.casa_members m on m.id=s.member_id where s.endpoint='https://fcm.googleapis.com/fcm/send/test-household-rollback'and m.household_id=hc)then raise exception 'FAIL: notification device did not follow current membership';end if;
 perform public.casa_household_switch(ha);perform public.casa_unsubscribe_push('https://fcm.googleapis.com/fcm/send/test-household-rollback');
 if exists(select 1 from public.casa_push_subscriptions where endpoint='https://fcm.googleapis.com/fcm/send/test-household-rollback')then raise exception 'FAIL: cross-house unsubscribe failed';end if;
 perform set_config('request.jwt.claim.sub',ub::text,true);perform public.casa_household_leave(ha);
 if public.casa_my_household()is not null then raise exception 'FAIL: no-membership account retained house';end if;
 if public.casa_pair_can_access(private_id)then raise exception 'FAIL: departed resident retained private access';end if;
 if exists(select 1 from casa_private.assignments(ha,d)where effective_member_id=b)then raise exception 'FAIL: departed resident still receives duties';end if;
 perform public.casa_join_household(code_a,'B',null);
 if (select id from public.casa_members where user_id=ub and household_id=ha)<>b then raise exception 'FAIL: rejoin duplicated profile';end if;
 perform set_config('request.jwt.claim.sub',uc::text,true);
 begin perform public.casa_household_switch(ha);raise exception 'FAIL: outsider switched into house';exception when raise_exception then if sqlerrm like 'FAIL:%'then raise;end if;end;
 if public.casa_household_list()<>'[]'::jsonb then raise exception 'FAIL: outsider can list houses';end if;
end $test$;
select 'PASS: join while already in another home, claim profile, multiple memberships, switching, default, private isolation, owner-only rename/delete, confirmation, leave and safe rejoin' as result;
rollback;
